    assert _auth.mask_value("Cookie", "abc") == "***"
    assert _auth.mask_value("X-Trace", "abcdef") == "abcdef", "非凭据头不该被掩码"
    assert "abcdef123456" not in _auth.summary({"Cookie": "abcdef123456"}), "摘要里出现了明文凭据"
