"""))
    _hits17.clear()
    assert [v["poc_id"] for v in engine.run_poc_on_target(_y_tags, _base_url17, {},
                                                          registry=_y_reg)] == ["smoke-wf-tag-a"]
    assert _hits17 == ["/a"], f"未被标签选中的模板不该跑：{_hits17}"
    _y_tags2 = engine.load_poc_file(_wpoc("wf-tags2.yaml", """
