    assert _login7(_cl126, {"username": "smoke126-admin", "password": "Passw0rd!123"},
                   environ_base={"REMOTE_ADDR": "198.51.100.212"}).status_code == 302
    _sh126 = _cl126.get("/settings").get_data(as_text=True)
