        assert "google.com" not in _targets169, "低置信不该自动递归"
        assert _p169["options"]["ext_depth"] == 1, "层数要递减（2 → 1）"
        assert _p169["stages"] == _rn169.depth_stages(["subdomain"]), "多层要把挖名阶段补上"
        _log169 = "\n".join(_rec169)
