    assert "$PIDFILE" in _src247 or "PIDFILE" in _src247, "重启必须只杀 pid 文件记着的进程，不许按名字乱杀"
    assert "git push" not in _src247, "update.sh 不替用户 push（推代码是本地角色的显式动作）"
